#!/usr/bin/env python3
"""references.bib of the manuscript: refs/verified.bib (generated by verify_refs.py from Crossref and arXiv metadata)
plus the documented corrections below and the manually checked vendor documents.

Author: Nasir Ali, C-DAC Noida.
usage: make_bib.py
"""
import os
import re

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.join(HERE, "..")

# key -> (field, new value, reason)
CORRECTIONS = [
    ("ali2026multifpga", "title",
     "Multi-FPGA Quantum Circuit Simulation: A Distributed Statevector Architecture on Four Xilinx Alveo U55C "
     "Accelerators", "Crossref record drops two spaces of the title"),
    ("ali2026multifpga", "note", "Under major revision, The Journal of Supercomputing", "decision of 2026-10-06 (author)"),
    ("tiwari2026fpga30", "author",
     "Tiwari, Abhishek and Ali, Nasir and Khan, Nadeem and Mazhar, Imam and Islur, Karan and Gupta, Himanshu and "
     "Kumar, Sachin and Tyagi, Pankaj", "author order as confirmed by the authors (the preprint record lists Ali first)"),
    ("tiwari2026fpga30", "note", "Under major revision, The Journal of Supercomputing", "status confirmed by the author"),
    ("ali2026qec", "note", "Under major revision", "status confirmed by the author"),
    ("google2023scaling", "author", "{Google Quantum AI}", "collaboration author list shortened to its name"),
    ("google2025below", "author", "{Google Quantum AI and Collaborators}", "collaboration author list shortened"),
]

# vendor documents, checked by hand (refs/verification_report.md, MANUAL)
MANUAL = """
@misc{amd_ds978,
  author = {{Advanced Micro Devices}},
  title = {{Alveo U55C Data Center Accelerator Card Data Sheet (DS978)}},
  year = {2023},
  howpublished = {\\url{https://docs.amd.com/r/en-US/ds978-u55c}}
}

@misc{amd_ug1399,
  author = {{Advanced Micro Devices}},
  title = {{Vitis High-Level Synthesis User Guide (UG1399), version 2023.2}},
  year = {2023},
  howpublished = {\\url{https://docs.amd.com/r/en-US/ug1399-vitis-hls}}
}

@misc{amd_xrt,
  author = {{Advanced Micro Devices}},
  title = {{Xilinx Runtime (XRT) Documentation}},
  year = {2023},
  howpublished = {\\url{https://xilinx.github.io/XRT/}}
}
"""


def set_field(entry, field, value):
    pat = re.compile(r"(\n  " + field + r" = \{)(.*?)(\},?\n)", re.S)
    if pat.search(entry):
        return pat.sub(lambda m: m.group(1) + value + m.group(3), entry, count=1)
    return entry.rstrip().rstrip("}").rstrip() + f",\n  {field} = {{{value}}}\n}}"


def main():
    src = open(os.path.join(ROOT, "refs", "verified.bib")).read()
    entries = {m.group(1): m.group(0) for m in re.finditer(r"@\w+\{([^,]+),.*?\n\}", src, re.S)}
    for key, field, value, _ in CORRECTIONS:
        entries[key] = set_field(entries[key], field, value)
    out = "% generated by scripts/make_bib.py from refs/verified.bib; corrections listed in that script\n\n"
    out += "\n\n".join(entries[k] for k in sorted(entries)) + "\n" + MANUAL
    open(os.path.join(ROOT, "references.bib"), "w").write(out)
    print(f"references.bib: {len(entries)} verified entries, {len(CORRECTIONS)} corrections, 3 vendor documents")


if __name__ == "__main__":
    main()
